public async checkModelDataDrift(modelId: string, customThreshold?: number) {
  if (!config.dataDriftAlerting.enabled) {
    return;
  }

  const threshold = customThreshold ?? config.dataDriftAlerting.defaultDriftThreshold;
  const score = calculateDriftScore([], {}); // Using mock data

  if (score > threshold) {
    await NotificationManager.sendAlert({
      type: 'DATA_DRIFT',
      payload: { 
        modelId,
        detectedScore: score,
        threshold,
        channels: config.dataDriftAlerting.notificationChannels
      }
    });
  }
}

import * as utils from '../src/utils';
import { NotificationManager } from '../src/module_77';
import { ModelMonitoringService } from '../src/module_48';

jest.mock('../src/module_77');

describe('Data Drift Alerting', () => {
  it('should trigger a notification when drift score exceeds threshold', async () => {
    const driftSpy = jest.spyOn(utils, 'calculateDriftScore').mockReturnValue(0.9);
    const notificationSpy = jest.spyOn(NotificationManager, 'sendAlert');

    // Assuming config can be modified for tests or is mocked
    config.dataDriftAlerting.enabled = true;
    config.dataDriftAlerting.defaultDriftThreshold = 0.8;

    const monitoringService = new ModelMonitoringService();
    await monitoringService.checkModelDataDrift('model-123');

    expect(driftSpy).toHaveBeenCalled();
    expect(notificationSpy).toHaveBeenCalledWith(expect.objectContaining({
      type: 'DATA_DRIFT',
      payload: expect.objectContaining({ modelId: 'model-123', detectedScore: 0.9 })
    }));
  });
});
